package repscr

import scala.language.implicitConversions
import scala.language.postfixOps

import Vwe._
import math._

// Intervals
case class Vwe(value: Double, error: Double) extends Ordered[Vwe] {
  this ensuring !(error < 0.0)

  override def toString = value.toString + "±" + error.toString

  def +(o: Vwe) = Vwe(value + o.value, maxDiff(lowerBound + o.lowerBound, upperBound + o.upperBound) / 2)
  def -(o: Vwe) = Vwe(value - o.value, maxDiff(lowerBound - o.upperBound, upperBound - o.lowerBound) / 2)
  def *(o: Vwe) = Vwe(value * o.value, maxDiff(lowerBound * o.lowerBound, lowerBound * o.upperBound, upperBound * o.lowerBound, upperBound * o.upperBound) /2)
  def /(o: Vwe) = Vwe(value / o.value, maxDiff(lowerBound / o.lowerBound, lowerBound / o.upperBound, upperBound / o.lowerBound, upperBound / o.upperBound) /2)
  def pow(p: Double) = Vwe(math.pow(value, p), maxDiff(math.pow(lowerBound, p), math.pow(upperBound, p)) / 2)

  def compare(o: Vwe) = value compare o.value match {
    case 0 => error compare o.error
    case x => x
  }

  def relativeError = error / value

  def lowerBound = value - error
  def upperBound = value + error

  def toInterval = (lowerBound, upperBound)

  def normalize(o: Any): Vwe = {
    val l = o match {
      case x: Vwe    => normalize(x.value)
      case x: Double => Vwe(if (value == 0.0) 0.0 else value / x, if (error == 0.0) 0 else error / abs(x))
      case x: Long   => normalize(x.toDouble)
      case x: Int    => normalize(x.toDouble)
      case _         => sys.error("No se puede normalizar Vwe wrt " + o.asInstanceOf[AnyRef].getClass)
    }
    assert(!l.value.isNaN || value.isNaN)
    assert(!l.error.isNaN || error.isNaN)
    l
  }

  def maxPoint(o: Any): Double = o match {
    case x: Vwe    => upperBound max x.upperBound
    case x: Double => x max upperBound
    case x: Float  => this maxPoint x.toDouble
    case x: Long   => this maxPoint x.toDouble
    case x: Int    => this maxPoint x.toDouble
    case _         => throw new IllegalArgumentException
  }

  def minPoint(o: Any): Double = o match {
    case x: Vwe    => lowerBound min x.lowerBound
    case x: Double => x min lowerBound
    case x: Float  => this minPoint x.toDouble
    case x: Long   => this minPoint x.toDouble
    case x: Int    => this minPoint x.toDouble
    case _         => throw new IllegalArgumentException
  }
}

object Vwe {
  implicit class DoublePlusMinus(val x: Double) extends AnyVal {
    def ±(e: Double) = Vwe(x, e)
  }
  implicit def FloatWrapper(x: Float): Vwe = Vwe(x, 0)
  implicit def DoubleWrapper(x: Double): Vwe = Vwe(x, 0)
  implicit def IntWrapper(x: Int): Vwe = Vwe(x, 0)
  implicit def LongWrapper(x: Long): Vwe = Vwe(x.toDouble, 0)

  def containing(values: Double*) = {
    val l = values.min / 2
    val u = values.max / 2
    Vwe(l + u, u - l)
  }

  def maxDiff(values: Double*) = {
    val l = values.min
    val u = values.max
    u - l
  }

  def fromSamples(l: Iterable[Double]) = fromSamplesStudent(l)

  def fromSamplesStudent(l: Iterable[Double], alpha: Double = 0.05): Vwe = {
    val mean = l.sum / l.size
    def square(a: Double) = a * a
    val stddev =
      if (l.size > 1) sqrt((l map { i => square(mean - i) } sum) / (l.size - 1))
      else 0.0
    Vwe(mean, stddev * studentT(alpha, l.size - 1) / sqrt(l.size))
  }

  def fromSamplesNormal(l: Iterable[Double], delta: Double = 1.96): Vwe = { // default for 0.95 confidence interval
    val mean = l.sum / l.size
    def square(a: Double) = a * a
    val stddev =
      if (l.size > 1) sqrt((l map { i => square(mean - i) } sum) / (l.size - 1))
      else 0.0
    Vwe(mean, stddev * delta / sqrt(l.size))
  }

  def average(l: Vwe*): Vwe = l.sum / l.size

  implicit object VweNumeric extends Numeric[Vwe] {
    def plus(x: Vwe, y: Vwe) = x + y
    def minus(x: Vwe, y: Vwe) = x - y
    def times(x: Vwe, y: Vwe) = x * y
    def negate(x: Vwe) = 0 - x
    def fromInt(x: Int) = Vwe(x, 0)
    def parseString(str: String) = ??? // TODO
    def toInt(x: Vwe) = x.value.toInt
    def toLong(x: Vwe) = x.value.toLong
    def toFloat(x: Vwe) = x.value.toFloat
    def toDouble(x: Vwe) = x.value.toDouble
    def compare(x: Vwe, y: Vwe) = x compare y
  }
}


