  def apply(alpha: Double, n: Int) = {
    def approxFromMapUpper[A](m: TreeMap[Int, A], n: Int) = (m.view filterKeys { _ >= n }).headOption.getOrElse(m.last)._2
    def approxFromMapLower[A](m: TreeMap[Double, A], n: Double) = (m.view filterKeys { _ <= n }).headOption.getOrElse(m.head)._2
    val row = studentTable.getOrElse(alpha, approxFromMapLower(studentTable, alpha))
    row.getOrElse(n, approxFromMapUpper(row, n))
  }
